solution.exercise.cpp:
#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
static bool search(const domino*d,size_t n,bool*used,domino*out,size_t k,int first,int last){if(k==n)return first==last;for(size_t i=0;i<n;i++)if(!used[i]){for(int flip=0;flip<2;flip++){int a=flip?d[i].right:d[i].left,b=flip?d[i].left:d[i].right;if(k&&a!=last)continue;used[i]=true;out[k].left=a;out[k].right=b;if(search(d,n,used,out,k+1,k?first:a,b))return true;used[i]=false;}}return false;}bool chain(const domino*d,size_t n,domino*out){if(!n)return true;bool*u=(bool*)calloc(n,sizeof(bool));bool ok=search(d,n,u,out,0,0,0);free(u);return ok;}

